from datetime import datetime
from os import path
from subprocess import Popen, PIPE
from typing import List
from ta_tti_parser.utils import get_robot_variable, get_simple_logger
import re


class TxtFileMerger(object):
    """Merge txt files into single one."""
    def __init__(self):
        _robot_output_dir = get_robot_variable('OUTPUT_DIR')
        self.robot_output_dir = _robot_output_dir if _robot_output_dir else '/tmp'
        self.logger = get_simple_logger(logger=None, logger_name='tti_parser_TxtFileMerger', stream=True,
                                        full_path=path.join(self.robot_output_dir, 'ta_tti_parser.log'))
        self.filenames_sorted = []
        self.merged_fn_path = ''
        self.files_path = ''
        self.merged_without_header = ''

    def merge(self, filenames, alias, direction):
        # type: (List[str], str, str) -> str
        """
        Merge txt files into single one.
        Sort contents of files based on row timestamp.
        :param filenames:
        :param direction:
        :param alias:
        :return:
        """
        self.filenames_sorted = sorted(filenames)
        self.files_path = path.abspath(path.dirname(self.filenames_sorted[0]))
        self.merged_fn_path = path.join(self.files_path,
                                        self._get_merged_filename(alias, direction, self._extract_timestamp()))
        self.merged_without_header = path.join(self.files_path, 'merged_without_header.txt')
        self._generate_actions()
        self._run_actions()
        return self.merged_fn_path

    def _generate_actions(self):
        """Insert many tail commands between first and second existing commands."""
        actions = [{'cmd': 'head -2 {} > {}', 'args': (self.filenames_sorted[0], self.merged_fn_path)},
                   {'cmd': 'sort {} -o {}', 'args': (self.merged_without_header, self.merged_without_header)},
                   {'cmd': 'cat {} >> {}', 'args': (self.merged_without_header, self.merged_fn_path)},
                   {'cmd': 'rm {}', 'args': (self.merged_without_header,)}]
        for num, filename in enumerate(self.filenames_sorted, 1):
            actions.insert(num, {'cmd': 'tail -n +3 {} >> {}', 'args': (filename, self.merged_without_header)})
        self.actions = actions

    def _extract_timestamp(self):
        regex = re.compile('.*[UD]L_?(.*)\\.txt')
        date_stamp = regex.match(self.filenames_sorted[-1])
        if date_stamp.groups()[0]:
            return list(date_stamp.groups())[0]
        return datetime.now().strftime("%d%b%Y%_H_%M_%S")

    @staticmethod
    def _get_merged_filename(alias, direction, stamp):
        merged_filename = ''.join(['_'.join(['merged', alias, direction, stamp]), '.txt'])
        return merged_filename

    def _run_actions(self):
        for action in self.actions:
            execute_shell_cmd(action['cmd'], *action['args'])
            self.logger.debug('Executed cmd: {}'.format(action['cmd'].format(*action['args'])))


def execute_shell_cmd(cmd, *args):
    # type: (str, List[str]) -> None
    """
    Execute shell cmd and fill cmd with provided arguments.
    :param cmd: shell cmd with placeholders for args
    :param args: will be inserted into shell cmd
    :return: None
    """
    process = Popen(cmd.format(*args), shell=True, stdout=PIPE, stderr=PIPE)
    check_return_status(process)


def check_return_status(process):
    # type: (Popen) -> None
    """
    Check if process succeeded.
    :param process:
    :return:
    :raises: IOError if return code != 0
    """
    _, err = process.communicate()
    if process.returncode != 0:
        raise IOError(err)
